Procedure CountVowels(Y)
    i = 1, V = 0
    while(i <= Y.LetterCount){
        if(ith letter of Y.Word is a vowel){
            V = V + 1
        }
        i = i + 1
    }
    return(V)
End CountVowels
Procedure CountConsonants(Y)
    i = 1, C = 0
    while(i <= Y.LetterCount){
        if(ith letter of Y.Word is not a vowel){
            C = C + 1
        }
        i = i + 1
    }
    return(C)
End CountConsonants
